    cacheStore,
    retriable,
    noteSourceResult,
    sourceBlocked,
    resetSourceBreaker,
    clampPanelPos,
    answerKeyOf,
    dismissExistingLeavePopup,
    effectiveDelay,
    extractAnswer,
    normalizeAnswer,
    mergeCandidates,
    extractAIAnswer,
    clipQuery,
    stripQueryEcho,
    removeFlatFragments,
